source.coverDecodeJs:
(() => {
    const view = result.readAllBytes();
    const isImage = (view[0] === 0xFF && view[1] === 0xD8) ||
        (view[0] === 0x89 && view[1] === 0x50) ||
        (view[0] === 0x47 && view[1] === 0x49) ||
        (view[0] === 0x52 && view[1] === 0x49);
    if (isImage) return result;
    const iv = view.slice(0, 16);
    const ciphertext = view.slice(16);
    const key = java.strToBytes('0B6666A0-BB59-1381-B746-a0E4C9AC');
    const cipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
    return cipher.decrypt(ciphertext);
})();

