source.loginUrl:
Url();

function getUrl() {
    try {
        let urls = [];
        Array.from(org.jsoup.Jsoup.parse(java.get("https://manwami.cc", {}).body()).select('.btnBox a'), x => {
            if (!x.text().includes('自测')) return urls.push(x.attr('href'));
            let src = java.ajax(x.attr('href'));
            let e = src.match(/e\s*=\s*(\[.+?\])/)[1]
            JSON.parse(e).map(u => urls.push(java.base64Decode(u)));
        });
        urls = Array.from(new Set(urls));
        java.log(urls.join('\n'));
        if (urls.length === 0) throw new Error('未获取到站源');
        let data = JSON.parse(source.getVariable());
        data.Urls = urls;
        source.setVariable(JSON.stringify(data, null, "\t"));
        java.toast(`获取到${urls.length}个站源\n${urls.join('\n')}`);
    } catch (e) {
        java.log(e.message)
        java.toast('获取失败，请检查网络');
    }
}

function setUrl(n) {
    let data = JSON.parse(source.getVariable());
    if (n + 1 > data.Urls.length) return java.toast(`暂时没有站源${n + 1}`);
    data.sourceurl = data.Urls[n];
    let timeNow = Date.now();
    try {
        let ty = java.get(data.Urls[n], {});
        if (!ty.body().includes('漫蛙')) throw new Error('站源失效');
    } catch (e) {
        java.log(e)
        java.toast(`\n当前站源：${data.Urls[n]}\n当前站源已失效，请检查网络或切换至其他站源!`);
        return;
    }
    let testTime = (Date.now() - timeNow) / 1000
    let imageSource = JSON.parse(java.ajax(data.Urls[n]).match(/window\.GLOBAL_IMAGE_ROUTES\s*=\s*(\[.*?\]);/)[1]).map(url => url.Url);
    data.imageSource = imageSource;
    source.setVariable(JSON.stringify(data, null, "\t"));
    java.toast(`当前站源已切换到：\n${data.Urls[n]}\n🔻解析时间：${testTime.toFixed(2)}🔻\n已获取${imageSource.length}条线路\n${imageSource.join('\n')}`);
}

function setImageSource(n) {
    let data = JSON.parse(source.getVariable());
    if (n + 1 > data.imageSource.length) return java.toast(`暂时没有站源${n + 1}`);
    if (data.imageSourceUrl === data.imageSource[n]) {
        data.imageSourceUrl = '';
        java.toast('已切换图片线路为默认');
    } else {
        data.imageSourceUrl = data.imageSource[n];
        java.toast(`当前图片线路已切换到：\n${data.imageSource[n]}`);
    }
    source.setVariable(JSON.stringify(data, null, "\t"));
}

function login() {}

function Login() {
    let username = String(result?.["用户名"]) || "axb";
    let password = String(result?.["密码"]) || "123456789@";
    let url = `${Url()}/api/user/login`;
    try {
        let response = JSON.parse(java.post(url, JSON.stringify({
            username,
            password
        }), {
            "x-requested-with": "XMLHttpRequest",
            "Content-Type": "application/json"
        }).body());
        if (!/successful/.test(response.msg)) return java.toast(response.msg);
        let token = response.data.token;
        source.putLoginHeader(JSON.stringify({
            "Authorization": "Bearer " + token,
            "Cookie": "authToken=" + token
        }));
        result["用户名"] = username;
        result["密码"] = password;
        source.putLoginInfo(JSON.stringify(result));
        java.toast(`\n用户：${username}\n登录成功！\n刷新发现即可查看更多标签`);
    } catch (e) {
        java.log(e.message);
        java.toast('请求失败，请检查网络状况！');
    }
}

function LoginOut() {
    source.removeLoginHeader();
    cookie.removeCookie(Url());
    java.toast('登出成功！');
}

