source.exploreUrl:
@js:
var cfg = {};
try { cfg = JSON.parse(String(source.getVariable() || '{}')) || {}; } catch (e) {}

var CH = [['男频', '♂', 1], ['女频', '♀', 2], ['出版', '✎', 3]];
var ch = CH.filter(function (c) { return c[0] == cfg.ch; })[0] || CH[0];
var DEF_OPEN = {'男频|热门': 1, '女频|热门': 1, '出版|热门': 1};
var open = cfg.open || DEF_OPEN;
var over = cfg.over || '-99', words = cfg.words || '-99', sort = cfg.sort || '0';

var OVER = [['全部状态', '-99'], ['完结', '1'], ['连载', '0']];
var WORDS = [['全部字数', '-99'], ['50万以下', '1'], ['50-100万', '2'], ['100-300万', '3'], ['300万以上', '4']];
var SORT = [['按热度', '0'], ['按更新', '1'], ['按评分', '2'], ['按新书', '3']];
function label(opts, v) { return (opts.filter(function (o) { return o[1] == v; })[0] || opts[0])[0]; }

var LAYOUT = {gap: 0.042, pad: 0.068, ch: 0.0368, shortMax: 3.3};

function textWidth(t) {
    var w = 0;
    for (var i = 0; i < t.length; i++) {
        var c = t.charCodeAt(i);
        if (c == 32) w += 0.32;
        else if (c < 128) w += 0.65;
        else if (c == 0xB7) w += 0.5;
        else if (c == 0x25CF) w += 0.9;
        else w += 1;
    }
    return w;
}

var s = [];

function pack(items, cols) {
    cols = cols || 4;
    var g = LAYOUT.gap, cell = (1 - g * (cols - 1)) / cols;
    var fit = (cell - LAYOUT.pad) / LAYOUT.ch;
    var queue = items.map(function (it) {
        return {it: it, span: Math.min(cols, Math.ceil(textWidth(it.title) / fit) || 1)};
    });
    while (queue.length) {
        var row = [], left = cols;
        while (queue.length && left > 0) {
            var k = 0;
            while (k < queue.length && queue[k].span > left) k++;
            if (k == queue.length) break;
            var x = queue.splice(k, 1)[0];
            row.push(x); left -= x.span;
        }
        for (; left > 0; left--) row.push({it: {title: '　', url: ''}, span: 1});
        row.forEach(function (x, i) {
            var st = {layout_flexGrow: x.span, layout_flexBasisPercent: Math.round((x.span / (cols + 1) + (x.span - 1) * g) * 1e4) / 1e4};
            if (i == 0) st.layout_wrapBefore = true;
            x.it.style = st;
            s.push(x.it);
        });
    }
}

function action(js) {
    return "(function(){var c={};try{c=JSON.parse(String(source.getVariable()||'{}'))||{};}catch(e){}"
        + js + "source.setVariable(JSON.stringify(c));java.refreshExplore();})()";
}
function button(title, js) {
    return {title: title, type: 'button', action: action(js)};
}
function bar(title, js) {
    var b = button(title, js);
    b.style = {layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true};
    s.push(b);
}
function optionRow(key, opts, cur) {
    pack(opts.map(function (o) {
        return button((o[1] == cur ? '● ' : '') + o[0], 'c[' + JSON.stringify(key) + ']=' + JSON.stringify(o[1]) + ';');
    }), 3);
}

pack(CH.map(function (c) {
    return button((c[0] == ch[0] ? '● ' : '') + c[1] + ' ' + c[0], 'c.ch=' + JSON.stringify(c[0]) + ';');
}), 3);

var filterTitle = '⚙ 筛选：' + label(OVER, over) + ' · ' + label(WORDS, words) + ' · ' + label(SORT, sort);
bar(filterTitle + (cfg.filt ? '　▾' : '　▸'), 'c.filt=!c.filt;');
if (cfg.filt) {
    optionRow('over', OVER, over);
    optionRow('words', WORDS, words);
    optionRow('sort', SORT, sort);
}

QM_TAGS[ch[0]].forEach(function (g) {
    var key = ch[0] + '|' + g[0];
    var items = g[1].split(',');
    var isOpen = !!open[key];
    bar((isOpen ? '▾ ' : '▸ ') + g[0] + '（' + items.length + '）',
        'var o=c.open||' + JSON.stringify(DEF_OPEN) + ';var k=' + JSON.stringify(key) + ';if(o[k])delete o[k];else o[k]=1;c.open=o;');
    if (!isOpen) return;
    var short = [], long = [];
    items.forEach(function (it) {
        var kv = it.split(':');
        var tag = {title: kv[0], url: '{{qmTag(' + ch[2] + ',' + kv[1] + ',page,' + over + ',' + words + ',' + sort + ')}}'};
        (textWidth(kv[0]) > LAYOUT.shortMax ? long : short).push(tag);
    });
    pack(short, 4);
    pack(long, 3);
});

JSON.stringify(s);

source.jsLib:
var QM_KEY = 'd3dGiJc651gSQ8w1';
var QM_AES = '242ccb8230d709e1';
var QM_BC = 'https://api-bc.wtzw.com';
var QM_KS = 'https://api-ks.wtzw.com';

function qmMd5(s) {
    var b = Packages.java.security.MessageDigest.getInstance('MD5')
        .digest(new Packages.java.lang.String(s).getBytes('UTF-8'));
    var h = '';
    for (var i = 0; i < b.length; i++) {
        var x = (b[i] & 0xff).toString(16);
        h += (x.length < 2 ? '0' : '') + x;
    }
    return h;
}

function qmSign(o) {
    return qmMd5(Object.keys(o).sort().map(function (k) { return k + '=' + o[k]; }).join('') + QM_KEY);
}

var QM_HEADERS = (function () {
    var h = {'app-version': '80400', 'platform': 'android', 'reg': '0', 'AUTHORIZATION': '',
             'application-id': 'com.****.reader', 'net-env': '1', 'channel': 'unknown', 'qm-params': ''};
    h.sign = qmSign(h);
    return JSON.stringify({headers: h});
})();

function qmUrl(base, path, params) {
    params.sign = qmSign(params);
    var q = Object.keys(params).map(function (k) {
        return k + '=' + encodeURIComponent(params[k]);
    }).join('&');
    return base + path + '?' + q + ',' + QM_HEADERS;
}

function qmSearch(key, page) {
    return qmUrl(QM_BC, '/search/v1/words', {gender: '3', imei_ip: '2937357107', page: page, wd: key});
}
function qmDetail(id) {
    return qmUrl(QM_BC, '/api/v4/book/detail', {id: id, imei_ip: '2937357107', teeny_mode: 0});
}
function qmToc(id) {
    return qmUrl(QM_KS, '/api/v1/chapter/chapter-list', {id: id});
}
function qmTag(gender, tid, page, over, words, sort) {
    var p = {gender: gender, need_filters: 1, page: page, tag_id: tid,
        over: over == null ? -99 : over, words: words == null ? -99 : words, sort: sort == null ? 0 : sort};
    if (gender == 1 || gender == 2) p.book_preference = gender;
    return qmUrl(QM_BC, '/api/v4/tag/index', p);
}

function qmContent(bid, cid, agent) {
    var p = {id: bid, chapterId: cid};
    if (agent) p.reader_agent = '1';
    return qmUrl(QM_KS, '/api/v1/chapter/content', p);
}

function qmChapterUrl(cid, md5, agent) {
    var s = cid + '/' + md5 + '/' + (agent == '1' ? '1' : '0');
    var b64 = Packages.java.util.Base64.getEncoder()
        .encodeToString(new Packages.java.lang.String(s).getBytes('UTF-8'));
    return 'data:;base64,' + b64 + ',{"type":"qm"}';
}

function qmUnzipEpub(b) {
    function u16(p) { return (b[p] & 0xff) | (b[p + 1] & 0xff) << 8; }
    function u32(p) { return (u16(p) | u16(p + 2) << 16) >>> 0; }
    var eocd = b.length - 22;
    while (eocd >= 0 && u32(eocd) != 0x06054b50) eocd--;
    if (eocd < 0) return '';
    var p = u32(eocd + 16), count = u16(eocd + 10), html = '';
    for (var i = 0; i < count; i++) {
        var method = u16(p + 10), csize = u32(p + 20), usize = u32(p + 24);
        var nlen = u16(p + 28), total = 46 + nlen + u16(p + 30) + u16(p + 32);
        var name = String(new Packages.java.lang.String(b, p + 46, nlen, 'UTF-8'));
        var lh = u32(p + 42);
        p += total;
        if (!/\.x?html?$/i.test(name)) continue;
        var start = lh + 30 + u16(lh + 26) + u16(lh + 28), text;
        if (method == 0) {
            text = new Packages.java.lang.String(b, start, csize, 'UTF-8');
        } else {
            var inf = new Packages.java.util.zip.Inflater(true);
            inf.setInput(b, start, csize);
            var out = Packages.java.util.Arrays.copyOf(b, usize);
            inf.inflate(out);
            inf.end();
            text = new Packages.java.lang.String(out, 'UTF-8');
        }
        var m = String(text).match(/<body[^>]*>([\s\S]*)<\/body>/i);
        if (m) html += m[1];
    }
    return html.replace(/<h\d[^>]*>[\s\S]*?<\/h\d>/gi, '')
               .replace(/&amp;/g, '&').trim();
}

function qmDecode(content) {
    var A = Packages.java.util.Arrays;
    var raw = Packages.java.util.Base64.getDecoder().decode(String(content));
    var key = new Packages.javax.crypto.spec.SecretKeySpec(new Packages.java.lang.String(QM_AES).getBytes('UTF-8'), 'AES');
    var iv = new Packages.javax.crypto.spec.IvParameterSpec(A.copyOfRange(raw, 0, 16));
    var c = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
    c.init(2, key, iv);
    var b = c.doFinal(A.copyOfRange(raw, 16, raw.length));
    if (b.length > 3 && b[0] == 0x50 && b[1] == 0x4B) return qmUnzipEpub(b);
    return String(new Packages.java.lang.String(b, 'UTF-8'));
}

