@js: //获取播放链接
let id = java.hexDecodeToString(result);
let url = `https://music.cpp-prog.com/api.php,{	"method": "post",
	"body": "types=url&id=${id}&source=netease"
}`;
result = cache.getFromMemory("wyy"+id);
if (!result) {
let rr=java.ajax(url);
result=java.getString('$.url',rr);
cache.putMemory("wyy"+id,result);
}
result;

